// Definition for singly-linked list.
struct Node {
    int data;
    struct Node* next;
};

// Function to move even nodes to the front of the linked list.
struct Node* moveEvenToFront(struct Node* head) {
    // Separate even and odd nodes into two lists.
    struct Node* evenStart = NULL;
    struct Node* evenEnd = NULL;
    struct Node* oddStart = NULL;
    struct Node* oddEnd = NULL;

    while (head != NULL) {
        if (head->data % 2 == 0) {
            // Even node, add to even list.
            if (evenStart == NULL) {
                evenStart = head;
                evenEnd = evenStart;
            } else {
                evenEnd->next = head;
                evenEnd = evenEnd->next;
            }
        } else {
            // Odd node, add to odd list.
            if (oddStart == NULL) {
                oddStart = head;
                oddEnd = oddStart;
            } else {
                oddEnd->next = head;
                oddEnd = oddEnd->next;
            }
        }
        // Move to next node.
        struct Node* temp = head;
        head = head->next;
        free(temp); // Free the current node to avoid memory leak.
    }

    // Connect even and odd lists.
    if (evenStart != NULL) {
        evenEnd->next = oddStart;
        return evenStart;
    } else {
        return oddStart;
    }
}

